const menu=document.querySelector('.menu-toggle');
const nav=document.querySelector('#mobile-nav');
function closeMenu(){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open menu');nav.classList.remove('is-open');nav.setAttribute('aria-hidden','true');}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu');nav.classList.toggle('is-open',open);nav.setAttribute('aria-hidden',String(!open));});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){closeMenu();menu.focus();}});
document.addEventListener('click',event=>{if(!event.target.closest('.header-inner'))closeMenu();});
matchMedia('(min-width:601px)').addEventListener('change',event=>{if(event.matches)closeMenu();});
if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('revealing');observer.unobserve(entry.target);}}),{threshold:.07});document.querySelectorAll('.reveal').forEach(element=>observer.observe(element));}

const localRoutes={'https://www.getyeda.com/':'/','https://www.getyeda.com/programs':'/programs/','https://www.getyeda.com/about':'/about/','https://www.getyeda.com/team':'/team/','https://www.getyeda.com/contact':'/contact/','https://www.getyeda.com/first-lesson-us':'/first-lesson-us/'};
document.querySelectorAll('a[href]').forEach(link=>{if(localRoutes[link.href])link.href=localRoutes[link.href];});
const subpageStyles=document.querySelector('link[href="/subpages.css"]');if(subpageStyles)subpageStyles.href='/subpages.css?v=5';
if(location.pathname.startsWith('/about')){const sources=document.querySelectorAll('video source');if(sources[0])sources[0].src='/assets/about-golan.mp4';if(sources[1])sources[1].src='/assets/about-michal.mp4';document.querySelectorAll('video').forEach(video=>video.load());}
if(location.pathname.startsWith('/about')){const quotes=document.querySelectorAll('.quote-panel blockquote');if(quotes[0])quotes[0].innerHTML='“I’ll try to briefly describe a phenomenal person named Golan because he’s so much more than a teacher, and even more than an educator.<br><br><strong>He’s a teacher raised to the power of teacher factorial!</strong><br><br>Yeda managed to instill in our daughter self-belief, learning skills - not just in math - and a rare kind of motivation and connection.<br><br>She actually looks forward to her lessons with him!<br><br><strong>The results speak for themselves: this year, she completed her matriculation in advanced Math with a score of 97%.</strong><br><br>I recommend him to everyone I know - and every student he works with seems to make an almost inexplicable leap in their learning.<br><br><strong>There’s only one explanation: Golan.</strong>”';if(quotes[1])quotes[1].innerHTML='“We have known Golan and Yeda, the institute he founded, for over seven years. During this time, we have seen Golan’s remarkable ability to work with students of all levels.<br><br>He meets each learner exactly where they are helping the strongest students reach new heights of excellence while also supporting those who find math more challenging to unlock their potential.<br><br><strong>His teaching goes far beyond technical knowledge: he brings curiosity, vitality, and positivity into every lesson, making the learning process not only effective but also enjoyable.</strong><br><br>What truly sets Golan and Yeda apart is their gift for transforming the way students relate to mathematics. For many, math can feel intimidating or discouraging, but Golan knows how to connect to each learner’s strengths and build confidence step by step. This approach nurtures a positive self-image and a deep sense of capability, which naturally extends to other areas of learning and even to life in general.<br><br>The impact of Golan and Yeda is not just academic it is deeply <strong>empowering and inspiring.</strong>”';}
if(location.pathname.startsWith('/first-lesson-us')){const videos=document.querySelectorAll('video');const sources=document.querySelectorAll('video source');if(sources[0])sources[0].src='/assets/53ad3d_8a4f3d9f93104913803d0b29021b0ca3.mp4';if(sources[1])sources[1].src='/assets/53ad3d_0deffe67a66e4ba688443ddbe975959b.mp4';if(videos[0])videos[0].poster='/assets/lesson-demo-poster.jpg';if(videos[1])videos[1].poster='/assets/first-lesson-poster.jpg';videos.forEach(video=>video.load());}
const bookingLink=[...document.querySelectorAll('a')].find(link=>link.textContent.includes('Open booking calendar'));if(bookingLink)bookingLink.href='https://www.getyeda.com/contact#booking';
if(['/about/','/team/','/contact/','/first-lesson-us/'].some(route=>location.pathname.startsWith(route))&&!document.querySelector('script[type="application/ld+json"]')){const schema=document.createElement('script');schema.type='application/ld+json';schema.textContent=JSON.stringify({'@context':'https://schema.org','@type':'EducationalOrganization','@id':'https://www.getyeda.com/#organization','name':'Yeda','legalName':'Yeda BV','url':'https://www.getyeda.com','logo':'https://static.wixstatic.com/media/53ad3d_cf234ef4a3904dd68211420e9cbc86e6~mv2.png/v1/fill/w_771%2Ch_401%2Cal_c%2Cq_85%2Cenc_avif%2Cquality_auto/Logo%20Vector%20Fixed.png','description':'Yeda provides Math and English tutoring for teens ages 13 to 18, building confidence and academic skills through personalized learning programs.','address':{'@type':'PostalAddress','streetAddress':'Tiensesteenweg 247','postalCode':'3360','addressLocality':'Bierbeek','addressCountry':'BE'},'areaServed':['Israel','United States','European Union'],'telephone':'+32467300331','email':'hello@getyeda.com','vatID':'BE1032162449','sameAs':['https://www.facebook.com/yeda.tutoring.il/','https://www.instagram.com/yeda.tutoring.il','https://www.tiktok.com/@yeda.il','https://www.youtube.com/@Yeda-by-Golan']});document.head.append(schema);}

if(location.pathname.startsWith('/team')){
  const profiles={
    golan:{name:'Golan',role:'Founder',bio:'Golan is the founder of Yeda and a dedicated educator with nearly 20 years of experience working with teens. His approach goes beyond tutoring - combining Math and English support with mentorship that builds confidence and resilience. Passionate and empathetic, Golan has guided students worldwide to succeed both in school and in themselves.'},
    rebecca:{name:'Rebecca',role:'Learning Specialist',bio:"With 40 years in education, including decades as a learning specialist at international schools, Dr. Rebecca Kimelman brings deep experience in learning differences, executive functioning, and helping students build genuine self-advocacy. She holds an Ed.D. in Education and has trained teachers and led accreditation work across schools on four continents.\n\nAt Yeda, Rebecca guides how every teacher works with students, through training, lesson observation, and direct feedback. She's the person behind the confidence-first method running through every session. Calm, precise, and endlessly curious about how each student actually learns."},
    simone:{name:'Simone',role:'English Teacher',bio:'Simone holds a PHD. in Egyptian Art & Archaeology and has decades of international teaching experience. She has worked in universities, museums, and publishing, always bringing clarity and encouragement to her students. At Yeda, she helps teens sharpen their English and grow in confidence.'},
    jacob:{name:'Jacob',role:'Math Teacher',bio:'With a background in both education and AI development, Jacob brings a unique blend of clarity, logic, and curiosity to every session. He holds a Bachelor of Education with specializations in Math and English, and has since expanded into computer science and large language model development.\n\nAt Yeda, Jacob helps students strengthen their math skills while building confidence, focus, and problem-solving strategies. His calm, thoughtful and fun approach makes even complex topics feel manageable.'},
    jason:{name:'Jason',role:'English Teacher',bio:'Jason is an English tutor for teens whose path to teaching began during his time in the Air Force. For over a decade, he has prepared students for Cambridge exams and university entry tests, making learning active and engaging. At Yeda, Jason helps teens build language skills, confidence, and resilience.'},
    jhon:{name:'John',role:'Math Teacher',bio:'With a Master’s in Education and professional teaching certification, he adapts his methods to meet each learner’s needs - from early number sense to advanced algebra. Skilled in both online and classroom settings, Jhon makes math engaging, interactive, and approachable.'},
    janice:{name:'Janice',role:'Math Teacher',bio:'Janice has nearly two decades of experience teaching math from grade school to college. With a Master’s in Education, she makes even the most complex topics clear, patient, and accessible, helping teens build both skills and confidence.'},
    deni:{name:'Dani Mariscal',role:'Mentor',bio:'Deni has spent years exploring how our thoughts and beliefs shape the way we learn, focus, and grow. Through practical mindset tools and simple daily techniques, they help teens move past fear, self-doubt, and perfectionism — building calm, confidence, and motivation from within.\n\nBeyond mentoring, Deni is a creative at heart; an abstract painter, cellist, and storyteller who creates short cinematic films that explore emotion, growth, and perspective. They believe creativity and mindset share the same foundation: how we see ourselves shapes what we create and who we become.'},
    itshak:{name:'Itshak Ben Meir',role:'Maths & Physics Teacher',bio:'Itshak is a mathematics and physics teacher with a Master’s degree in Mechanical Engineering from the Technion Institute of Technology. He has taught an academic accelerated mathematics program for teens and has years of experience working with students of all ages and levels. Itshak is known for a clear, supportive approach that emphasizes logical thinking and deep understanding. He tailors a personalized learning plan for each student according to their individual needs and learning style, bringing a fresh, light, and engaging atmosphere even to complex material. Itshak truly loves mathematics and believes that solving math problems can be an exciting and empowering experience.'},
    kelly:{name:'Kelly',role:'Educational Mentor',bio:'Kelly is an innovative educator with over 20 years in teaching, curriculum design, and leadership. She creates learning experiences that are practical, engaging, and empowering - guiding both students and teachers to succeed.'}
  };
  const dialog=document.createElement('dialog');dialog.className='profile-dialog';dialog.setAttribute('aria-labelledby','profile-name');dialog.innerHTML='<button class="profile-close" type="button" aria-label="Close profile">×</button><div class="profile-layout"><img class="profile-photo" alt=""><div class="profile-copy"><h2 id="profile-name"></h2><p class="profile-role"></p><p class="profile-bio"></p></div></div>';document.body.append(dialog);
  document.querySelectorAll('.profile-button').forEach(button=>button.addEventListener('click',()=>{const profile=profiles[button.dataset.profile];dialog.querySelector('#profile-name').textContent=profile.name;dialog.querySelector('.profile-role').textContent=profile.role;dialog.querySelector('.profile-bio').textContent=profile.bio;const photo=dialog.querySelector('.profile-photo');photo.src=button.closest('.person').querySelector('img').src;photo.alt=profile.name;dialog.showModal();}));
  dialog.querySelector('.profile-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close();});
}
